    S(F, 840, '\'<p class="hint">Avec les <b>calques</b>, les repères et le cartouche partent dans \'\r\n      + \'des groupes <b>/OCG</b> nommés : l’imprimeur les décoche au lieu d’éditer le flux. \'\r\n      + \'C’est du <span class="mono">%PDF-1.5</span>, donc incompatible avec une \'\r\n      + \'revendication PDF/X-3 — le contrôle avant vol le dit et propose de décocher. \'\r\n      + \'La <b>page</b> suit par défaut la grille du raster (2480 px à 300 DPI = 595,2 pt) \'\r\n      + \'pour que le PDF et la planche PNG décrivent la même feuille ; « format nominal » \'\r\n      + \'écrit 595,2756 x 841,8898 pt et centre l’imposition dedans.</p>\'', '\'<p class="hint">\' + dzT("cartes.print.aide_calques") + \'</p>\'', {'cartes.print.aide_calques': ('Avec les <b>calques</b>, les repères et le cartouche partent dans des groupes <b>/OCG</b> nommés : l’imprimeur les décoche au lieu d’éditer le flux. C’est du <span class="mono">%PDF-1.5</span>, donc incompatible avec une revendication PDF/X-3 — le contrôle avant vol le dit et propose de décocher. La <b>page</b> suit par défaut la grille du raster (2480 px à 300 DPI = 595,2 pt) pour que le PDF et la planche PNG décrivent la même feuille ; « format nominal » écrit 595,2756 x 841,8898 pt et centre l’imposition dedans.', 'With <b>layers</b>, marks and slug go into named <b>/OCG</b> groups: the printer unticks them instead of editing the stream. That is <span class="mono">%PDF-1.5</span>, so incompatible with a PDF/X-3 claim — preflight says so and offers to untick. By default the <b>page</b> follows the raster grid (2480 px at 300 DPI = 595.2 pt) so the PDF and the PNG sheet describe the same sheet; “nominal size” writes 595.2756 x 841.8898 pt and centers the imposition in it.')}),
    S(F, 848, '\'<button class="btn strong" type="button" data-act="png">Planche PNG <b>(P)</b></button>\'', '\'<button class="btn strong" type="button" data-act="png">\' + dzT("cartes.print.btn_planche_png") + \' <b>(P)</b></button>\'', {'cartes.print.btn_planche_png': ('Planche PNG', 'PNG sheet')}),
    S(F, 849, '\'<button class="btn strong" type="button" data-act="pdf">PDF multipage <b>(D)</b></button>\'', '\'<button class="btn strong" type="button" data-act="pdf">\' + dzT("cartes.print.btn_pdf") + \' <b>(D)</b></button>\'', {'cartes.print.btn_pdf': ('PDF multipage', 'Multipage PDF')}),
    S(F, 850, '\'<button class="btn" type="button" data-act="mire" title="Deux pages à imprimer en recto-verso sur VOTRE imprimante : un vernier au dixième de millimètre mesure le décalage réel de la machine (le PDF, lui, est déjà miroir)">\' + ICO("dz-action-telecharger", 16, "cf-ic") + \'Mire recto-verso (PDF)</button>\'', '\'<button class="btn" type="button" data-act="mire" title="\' + dzT("cartes.print.mire_titre") + \'">\' + ICO("dz-action-telecharger", 16, "cf-ic") + dzT("cartes.print.mire") + \'</button>\'', {'cartes.print.mire_titre': ('Deux pages à imprimer en recto-verso sur VOTRE imprimante : un vernier au dixième de millimètre mesure le décalage réel de la machine (le PDF, lui, est déjà miroir)', "Two pages to print duplex on YOUR printer: a vernier reading to a tenth of a millimetre measures the machine's real offset (the PDF itself is already mirrored)"), 'cartes.print.mire': ('Mire recto-verso (PDF)', 'Duplex test chart (PDF)')}),
    S(F, 852, '\'<p class="hint">Le PDF porte les <b>trois</b> cadres emboîtés sur chaque page — \'\r\n      + \'<b>/BleedBox</b> (fond perdu) &#8835; <b>/TrimBox</b> (coupe) &#8835; <b>/ArtBox</b> \'\r\n      + \'(zone sûre) — et des traits de coupe <b>vectoriels</b>, à une distance \'\r\n      + \'<b>mesurée</b> de la carte la plus proche.</p>\'', '\'<p class="hint">\' + dzT("cartes.print.aide_cadres") + \'</p>\'', {'cartes.print.aide_cadres': ('Le PDF porte les <b>trois</b> cadres emboîtés sur chaque page — <b>/BleedBox</b> (fond perdu) &#8835; <b>/TrimBox</b> (coupe) &#8835; <b>/ArtBox</b> (zone sûre) — et des traits de coupe <b>vectoriels</b>, à une distance <b>mesurée</b> de la carte la plus proche.', 'The PDF carries the <b>three</b> nested boxes on every page — <b>/BleedBox</b> (bleed) &#8835; <b>/TrimBox</b> (cut) &#8835; <b>/ArtBox</b> (safe area) — and <b>vector</b> crop marks at a <b>measured</b> distance from the nearest card.')}),
    S(F, 859, '\'<details class="grp" open><summary>Couleur et prépresse — intention de sortie, séparation, repérage</summary>\'', '\'<details class="grp" open><summary>\' + dzT("cartes.print.titre_couleur") + \'</summary>\'', {'cartes.print.titre_couleur': ('Couleur et prépresse — intention de sortie, séparation, repérage', 'Color and prepress — output intent, separation, registration')}),
    S(F, 861, '\'<label class="fld"><span class="lbl">Intention de sortie (/OutputIntents)</span>\'', '\'<label class="fld"><span class="lbl">\' + dzT("cartes.print.intention") + \'</span>\'', {'cartes.print.intention': ('Intention de sortie (/OutputIntents)', 'Output intent (/OutputIntents)')}),
    S(F, 865, '\'<label class="fld"><span class="lbl">Espace des visuels</span>\'', '\'<label class="fld"><span class="lbl">\' + dzT("cartes.print.espace_visuels") + \'</span>\'', {'cartes.print.espace_visuels': ('Espace des visuels', 'Artwork color space')}),
    L(F, 866, '"RVB étiqueté"', 'cartes.print.rvb_etiquete', 'RVB étiqueté', 'Tagged RGB'),
