    S(F, 868, '\'<label class="fld"><span class="lbl">Encre des repères</span>\'', '\'<label class="fld"><span class="lbl">\' + dzT("cartes.print.encre_reperes") + \'</span>\'', {'cartes.print.encre_reperes': ('Encre des repères', 'Mark ink')}),
