    S(F, 1158, '\'16 bits = <b>conteneur</b>, mesuré sur un <b>témoin écrit</b> avec ces \'\r\n            + \'réglages (rampe de 256 niveaux, \' + AUDIT.depth["16"].bytes + \' octets) : \'\r\n            + AUDIT.depth["16"].samples.toLocaleString("fr-FR") + \' échantillons, <b>\'\r\n            + AUDIT.depth["16"].distinct + \' valeurs distinctes</b> = \'\r\n            + nfx(AUDIT.depth["16"].useful_bits, 2) + \' bits utiles\'', 'dzT("cartes.print.cr_16_mesure", { octets: AUDIT.depth["16"].bytes, ech: AUDIT.depth["16"].samples.toLocaleString("fr-FR"), dist: AUDIT.depth["16"].distinct, utiles: nfx(AUDIT.depth["16"].useful_bits, 2) })', {'cartes.print.cr_16_mesure': ('16 bits = <b>conteneur</b>, mesuré sur un <b>témoin écrit</b> avec ces réglages (rampe de 256 niveaux, {octets} octets) : {ech} échantillons, <b>{dist} valeurs distinctes</b> = {utiles} bits utiles', '16 bits = <b>container</b>, measured on a <b>written sample</b> with these settings (256-level ramp, {octets} bytes): {ech} samples, <b>{dist} distinct values</b> = {utiles} useful bits')}),
    S(F, 1164, "', toutes multiples de <b>257</b> — donc une source 8 bits élargie, '\r\n                + 'exactement ce qui est annoncé.'", 'dzT("cartes.print.cr_257")', {'cartes.print.cr_257': (', toutes multiples de <b>257</b> — donc une source 8 bits élargie, exactement ce qui est annoncé.', ', all multiples of <b>257</b> — so an upscaled 8-bit source, exactly as announced.')}),
