    S(F, 1202, "(bon ? 'Miroir mesuré' : 'MIROIR FAUX') + ' : écart ' + nfx(um, 1)\r\n      + ' µm</b> — retournement '", '(bon ? dzT("cartes.print.dx_ok", { um: nfx(um, 1) }) : dzT("cartes.print.dx_faux", { um: nfx(um, 1) })) + \'</b> — \' + dzT("cartes.print.dx_retournement") + \' \'', {'cartes.print.dx_ok': ('Miroir mesuré : écart {um} µm', 'Mirror measured: deviation {um} µm'), 'cartes.print.dx_faux': ('MIROIR FAUX : écart {um} µm', 'MIRROR WRONG: deviation {um} µm'), 'cartes.print.dx_retournement': ('retournement', 'flip')}),
    L(F, 1204, '"bord long (la colonne s’inverse)"', 'cartes.print.dx_long', 'bord long (la colonne s’inverse)', 'long edge (the column flips)'),
    L(F, 1205, '"bord court (la ligne s’inverse)"', 'cartes.print.dx_court', 'bord court (la ligne s’inverse)', 'short edge (the row flips)'),
    S(F, 1209, "'Chaque verso tombe derrière son recto : écart mesuré case par case '\r\n          + 'entre sa position et la position miroir du recto'", 'dzT("cartes.print.dx_bon")', {'cartes.print.dx_bon': ('Chaque verso tombe derrière son recto : écart mesuré case par case entre sa position et la position miroir du recto', "Every back lands behind its front: deviation measured cell by cell between its position and the front's mirror position")}),
    L(F, 1211, "'Le verso ne tombe PAS derrière son recto'", 'cartes.print.dx_mauvais', 'Le verso ne tombe PAS derrière son recto', 'The back does NOT land behind its front'),
    S(F, 1212, "' — <b>même mesure côté backend</b> (' + nfx(bum, 1) + ' µm), '\r\n        + 'sur la géométrie qu’il écrira.'", 'dzT("cartes.print.dx_accord", { um: nfx(bum, 1) })', {'cartes.print.dx_accord': (' — <b>même mesure côté backend</b> ({um} µm), sur la géométrie qu’il écrira.', ' — <b>same measurement on the backend</b> ({um} µm), on the geometry it will write.')}),
    L(F, 1214, "' (pas encore confirmé par le backend).'", 'cartes.print.dx_pas_confirme', ' (pas encore confirmé par le backend).', ' (not yet confirmed by the backend).'),
    S(F, 1215, "' — backend : ' + nfx(bum, 1) + ' µm.'", 'dzT("cartes.print.dx_backend", { um: nfx(bum, 1) })', {'cartes.print.dx_backend': (' — backend : {um} µm.', ' — backend: {um} µm.')}),
    S(F, 1244, "'Sceau prismatique actif, mais <b>hors portée impression</b> : cocher '\r\n          + '« impression » dans le groupe « Sceau prismatique » du panneau <b>Cadre</b>. '\r\n          + 'Le PDF ne portera ni encre d’appoint, ni calque de foil.'", 'dzT("cartes.print.foil_hors_portee")', {'cartes.print.foil_hors_portee': ('Sceau prismatique actif, mais <b>hors portée impression</b> : cocher « impression » dans le groupe « Sceau prismatique » du panneau <b>Cadre</b>. Le PDF ne portera ni encre d’appoint, ni calque de foil.', 'Prismatic Seal active, but <b>outside print scope</b>: tick “print” in the “Prismatic Seal” group of the <b>Frame</b> panel. The PDF will carry neither spot ink nor a foil layer.')}),
    S(F, 1247, "'Aucun <b>Sceau prismatique</b> sur ce jeu : rien à dorer. Le contour '\r\n          + 'holographique se coche dans le panneau <b>Cadre</b>.'", 'dzT("cartes.print.foil_aucun")', {'cartes.print.foil_aucun': ('Aucun <b>Sceau prismatique</b> sur ce jeu : rien à dorer. Le contour holographique se coche dans le panneau <b>Cadre</b>.', 'No <b>Prismatic Seal</b> on this deck: nothing to foil. The holographic outline is ticked in the <b>Frame</b> panel.')}),
    S(F, 1252, '\'<div class="cf-print-pf-ok muted">Sceau en portée impression — \'\r\n        + \'les millimètres tracés sont calculés par le backend, et le plan n’a pas \'\r\n        + \'encore répondu.</div>\'', '\'<div class="cf-print-pf-ok muted">\' + dzT("cartes.print.foil_attente") + \'</div>\'', {'cartes.print.foil_attente': ('Sceau en portée impression — les millimètres tracés sont calculés par le backend, et le plan n’a pas encore répondu.', 'Seal in print scope — the drawn millimetres are computed by the backend, and the layout has not answered yet.')}),
    S(F, 1263, '\'Le <b>retrait du filet est négatif</b> dans le document (\'\r\n        + nfx(f.edge_asked_mm, 2) + \' mm) : l’anneau tomberait hors de la carte, et sur \'\r\n        + \'une planche il traverserait le trait de coupe de la carte voisine. La plaque \'\r\n        + \'a été ramenée au trait de coupe ; remettre <span class="mono">edge_mm</span> \'\r\n        + \'entre 0 et 8 mm dans le panneau Cadre. <b>L’export est refusé</b> d’ici là.\'', 'dzT("cartes.print.foil_negatif", { v: nfx(f.edge_asked_mm, 2) })', {'cartes.print.foil_negatif': ('Le <b>retrait du filet est négatif</b> dans le document ({v} mm) : l’anneau tomberait hors de la carte, et sur une planche il traverserait le trait de coupe de la carte voisine. La plaque a été ramenée au trait de coupe ; remettre <span class="mono">edge_mm</span> entre 0 et 8 mm dans le panneau Cadre. <b>L’export est refusé</b> d’ici là.', 'The <b>border inset is negative</b> in the document ({v} mm): the ring would fall outside the card, and on a sheet it would cross the neighbouring card\'s cut line. The plate has been brought back to the cut line; set <span class="mono">edge_mm</span> back between 0 and 8 mm in the Frame panel. <b>Export is refused</b> until then.')}),
    L(F, 1274, "'Aucun anneau à dorer : '", 'cartes.print.foil_pas_anneau', 'Aucun anneau à dorer : ', 'No ring to foil: '),
    S(F, 1276, "'entre le filet (posé à <b>' + nfx(f.edge_mm, 2) + ' mm</b> de la coupe) et '\r\n          + 'la fenêtre d’illustration il ne reste que <b>' + nfx(f.cap_mm, 2)\r\n          + ' mm</b>, sous le trait minimal de ' + nf(f.min_mm, 1) + ' mm. '\r\n          + '<b>Rapprocher le filet de la coupe ou reculer la fenêtre</b> (panneau Cadre).'", 'dzT("cartes.print.foil_place", { edge: nfx(f.edge_mm, 2), cap: nfx(f.cap_mm, 2), min: nf(f.min_mm, 1) })', {'cartes.print.foil_place': ('entre le filet (posé à <b>{edge} mm</b> de la coupe) et la fenêtre d’illustration il ne reste que <b>{cap} mm</b>, sous le trait minimal de {min} mm. <b>Rapprocher le filet de la coupe ou reculer la fenêtre</b> (panneau Cadre).', 'between the border (set <b>{edge} mm</b> from the cut) and the art window only <b>{cap} mm</b> remain, below the minimum stroke of {min} mm. <b>Move the border closer to the cut or pull the window back</b> (Frame panel).')}),
    S(F, 1280, "'la <b>largeur demandée</b> par le document vaut <b>' + nfx(f.asked_mm, 2)\r\n          + ' mm</b>, alors que la place n’y est pour rien (' + nfx(f.cap_mm, 2)\r\n          + ' mm disponibles). <b>Régler la largeur de bande du Sceau</b> dans le '\r\n          + 'panneau Cadre.'", 'dzT("cartes.print.foil_largeur", { asked: nfx(f.asked_mm, 2), cap: nfx(f.cap_mm, 2) })', {'cartes.print.foil_largeur': ('la <b>largeur demandée</b> par le document vaut <b>{asked} mm</b>, alors que la place n’y est pour rien ({cap} mm disponibles). <b>Régler la largeur de bande du Sceau</b> dans le panneau Cadre.', "the <b>width requested</b> by the document is <b>{asked} mm</b>, while space is not the issue ({cap} mm available). <b>Adjust the Seal's band width</b> in the Frame panel.")}),
    L(F, 1284, "' Le PDF partira sans masque de foil.'", 'cartes.print.foil_sans_masque', ' Le PDF partira sans masque de foil.', ' The PDF will go out without a foil mask.'),
    S(F, 1287, "'Trait de <b>' + nfx(f.width_mm, 2) + ' mm</b>, sous le minimum '\r\n          + 'd’un imprimeur foil (' + nf(f.min_mm, 1) + ' mm) : l’export sera refusé. '\r\n          + 'Aucun curseur ne descend là — cette largeur vient du document lui-même.'", 'dzT("cartes.print.foil_trait_min", { w: nfx(f.width_mm, 2), min: nf(f.min_mm, 1) })', {'cartes.print.foil_trait_min': ('Trait de <b>{w} mm</b>, sous le minimum d’un imprimeur foil ({min} mm) : l’export sera refusé. Aucun curseur ne descend là — cette largeur vient du document lui-même.', "Stroke of <b>{w} mm</b>, below a foil printer's minimum ({min} mm): export will be refused. No slider goes that low — this width comes from the document itself.")}),
    S(F, 1292, "'Anneau <b>' + esc(f.kind) + '</b> de <b>'\r\n        + nfx(f.width_mm, 2) + ' mm</b>, posé à <b>' + nfx(f.edge_mm, 2) + ' mm</b> du '\r\n        + 'trait de coupe'", 'dzT("cartes.print.foil_anneau", { kind: esc(f.kind), w: nfx(f.width_mm, 2), edge: nfx(f.edge_mm, 2) })', {'cartes.print.foil_anneau': ('Anneau <b>{kind}</b> de <b>{w} mm</b>, posé à <b>{edge} mm</b> du trait de coupe', '<b>{kind}</b> ring of <b>{w} mm</b>, set <b>{edge} mm</b> from the cut line')}),
    S(F, 1296, '\' — il en faut \' + nf(f.trim_mm, 1) + \'. Monter le retrait du filet \'\r\n          + \'(<span class="mono">edge_mm</span>) au-delà de \' + nf(f.trim_mm, 1)\r\n          + \' mm dans le panneau Cadre, ce qui déplace aussi le filet extérieur, ou \'\r\n          + \'accepter la variance de fabrication de \' + esc(f.variance) + \'. \'\r\n          + \'<b>Avertissement, pas erreur</b> : l’export part quand même.\'', 'dzT("cartes.print.foil_proche", { t: nf(f.trim_mm, 1), variance: esc(f.variance) })', {'cartes.print.foil_proche': (' — il en faut {t}. Monter le retrait du filet (<span class="mono">edge_mm</span>) au-delà de {t} mm dans le panneau Cadre, ce qui déplace aussi le filet extérieur, ou accepter la variance de fabrication de {variance}. <b>Avertissement, pas erreur</b> : l’export part quand même.', ' — {t} is required. Raise the border inset (<span class="mono">edge_mm</span>) above {t} mm in the Frame panel, which also moves the outer border, or accept the manufacturing variance of {variance}. <b>Warning, not an error</b>: the export still goes out.')}),
    S(F, 1301, "' : au-delà des ' + nf(f.trim_mm, 1) + ' mm exigés.'", 'dzT("cartes.print.foil_audela", { t: nf(f.trim_mm, 1) })', {'cartes.print.foil_audela': (' : au-delà des {t} mm exigés.', ': beyond the {t} mm required.')}),
    S(F, 1302, '\'Le PDF portera l’encre d’appoint <span class="mono">/Separation \'\r\n        + \'« Foil »</span> en surimpression, dans le calque « \' + esc(f.layer) + \' »\'\r\n        + (st().layers ? \'\' : \' — mais la case <b>calques optionnels</b> est décochée : \'\r\n          + \'la plaque reste lisible, l’imprimeur ne pourra pas l’isoler d’un clic\')\r\n        + \'. Repli raster : PNG 1 bit \' + FOILDPI + \' dpi, noir = dorure.\'', 'dzT("cartes.print.foil_pdf", { calque: esc(f.layer) })\r\n        + (st().layers ? \'\' : dzT("cartes.print.foil_sans_calques"))\r\n        + dzT("cartes.print.foil_repli", { dpi: FOILDPI })', {'cartes.print.foil_pdf': ('Le PDF portera l’encre d’appoint <span class="mono">/Separation « Foil »</span> en surimpression, dans le calque « {calque} »', 'The PDF will carry the spot ink <span class="mono">/Separation “Foil”</span> as overprint, in the “{calque}” layer'), 'cartes.print.foil_sans_calques': (' — mais la case <b>calques optionnels</b> est décochée : la plaque reste lisible, l’imprimeur ne pourra pas l’isoler d’un clic', " — but the <b>optional layers</b> box is unticked: the plate stays readable, but the printer can't isolate it in one click"), 'cartes.print.foil_repli': ('. Repli raster : PNG 1 bit {dpi} dpi, noir = dorure.', '. Raster fallback: 1-bit PNG {dpi} dpi, black = foil.')}),
    S(F, 1322, '\'<span class="cf-print-bad">Aucune intention : le fichier ne dira pas \'\r\n        + \'dans quel espace il a été fabriqué.</span>\'', '\'<span class="cf-print-bad">\' + dzT("cartes.print.ir_aucune") + \'</span>\'', {'cartes.print.ir_aucune': ('Aucune intention : le fichier ne dira pas dans quel espace il a été fabriqué.', "No intent: the file won't say which color space it was made in.")}),
    S(F, 1333, '\'Écrit dans le PDF : <b>/OutputIntents</b> · sous-type <b class="mono">\'', 'dzT("cartes.print.ir_ecrit") + \'<b class="mono">\'', {'cartes.print.ir_ecrit': ('Écrit dans le PDF : <b>/OutputIntents</b> · sous-type ', 'Written into the PDF: <b>/OutputIntents</b> · subtype ')}),
    S(F, 1334, "'</b> · identifiant <b>'", '\'</b> · \' + dzT("cartes.print.ir_identifiant") + \' <b>\'', {'cartes.print.ir_identifiant': ('identifiant', 'identifier')}),
    S(F, 1337, '\' · profil ICC embarqué de <b>\' + bpf.profile_bytes + \' octets</b>\'\r\n          + (bpf.cls ? \' (classe <span class="mono">\' + esc(bpf.cls) + \'</span>)\' : \'\')', 'dzT("cartes.print.ir_profil", { n: bpf.profile_bytes })\r\n          + (bpf.cls ? dzT("cartes.print.ir_classe", { cls: esc(bpf.cls) }) : \'\')', {'cartes.print.ir_profil': (' · profil ICC embarqué de <b>{n} octets</b>', ' · embedded ICC profile of <b>{n} bytes</b>'), 'cartes.print.ir_classe': (' (classe <span class="mono">{cls}</span>)', ' (class <span class="mono">{cls}</span>)')}),
    L(F, 1339, "' · condition normalisée du registre ICC (profil embarqué facultatif)'", 'cartes.print.ir_condition', ' · condition normalisée du registre ICC (profil embarqué facultatif)', ' · standard condition from the ICC registry (embedded profile optional)'),
    S(F, 1342, '\' · <b class="cf-print-good">conformité \' + esc(bpf.version) + \'</b> \'\r\n            + \'revendiquée (version + XMP pdfxid + /Trapped + en-tête %PDF-1.4)\'', 'dzT("cartes.print.ir_claim", { v: esc(bpf.version) })', {'cartes.print.ir_claim': (' · <b class="cf-print-good">conformité {v}</b> revendiquée (version + XMP pdfxid + /Trapped + en-tête %PDF-1.4)', ' · <b class="cf-print-good">{v} compliance</b> claimed (version + XMP pdfxid + /Trapped + %PDF-1.4 header)')}),
    L(F, 1344, "' · <b>aucune revendication PDF/X</b> — '", 'cartes.print.ir_sans_claim', ' · <b>aucune revendication PDF/X</b> — ', ' · <b>no PDF/X claim</b> — '),
