    S(F, 1360, '\'<div class="cf-print-pf-ok">écriture d’un PDF témoin, puis relecture des octets…</div>\'', '\'<div class="cf-print-pf-ok">\' + dzT("cartes.print.audit_en_cours") + \'</div>\'', {'cartes.print.audit_en_cours': ('écriture d’un PDF témoin, puis relecture des octets…', 'writing a sample PDF, then reading its bytes back…')}),
